 gm.querySelectorAll('*').forEach(function(e){ if(e.closest('.gm-screen:not(.is-on)')||e.closest('.gm-drawer:not(.is-on)')||e.closest('.gm-pop:not(.is-on)')||e.closest('.gm-gift:not(.is-on)')||e.closest('.gm-story__bg')||e.closest('.gm-rest__bg')||e.closest('.e14-art')||e.closest('.board')||e.closest('.gm-veil')||e.closest('.e14-fx')||e.closest('svg')) return;
